// =============================================================================
// ==== tb/unit/tb_resv_ctrl.sv   (tests: U10)
// =============================================================================
`ifdef RUN_TB_RESV_CTRL
// @tests    U10
`timescale 1ns/1ps
// `include "tb_macros.svh": inlined earlier in this bundle

module resv_tester
  import noc_pkg::*;
  import sched_pkg::*;
#(
  parameter int N      = 4,
  parameter int BM     = 10,
  parameter int TMODE  = TM_TIGHT,
  parameter int SMALL  = 0,          // 1: SPACE = BM, the smallest legal bypass space
  parameter int SID    = 700
) (
  input  logic go,
  output logic done
);
  localparam int S     = s_setup(N);
  localparam int T     = t_sub(N, BM, TMODE);
  localparam int HM    = hmax(N);
  localparam int SPACE = (SMALL != 0) ? BM : byp_space(N, BM, TMODE);
  localparam int LEN   = slot_len(N, T);
  localparam int RING  = 512;
  localparam int RB    = $clog2(RING);
  localparam int CW    = $clog2(SPACE + 1);

  logic          clk   = 1'b0;
  logic          rst_n = 1'b0;
  logic          dec = 1'b0, dec_s0 = 1'b0, dec_mode = 1'b0, push = 1'b0, pop = 1'b0;
  node_id_t      dec_src = '0;
  hop_t          dec_hops = '0;
  la_t           la = '0;
  cx_t           cx;
  logic [CW-1:0] res_o, fill_o;

  resv_ctrl #(.B_MAX(BM), .SPACE(SPACE), .GAP0(S), .GAPK(T)) u_dut (
    .clk_i      (clk),
    .rst_ni     (rst_n),
    .dec_i      (dec),
    .dec_s0_i   (dec_s0),
    .dec_loc_i  (1'b0),                  // design B's timetable (designs C, D: TL tests)
    .dec_src_i  (dec_src),
    .dec_mode_i (dec_mode),
    .dec_hops_i (dec_hops),
    .la_i       (la),
    .push_i     (push),
    .pop_i      (pop),
    .cx_o       (cx),
    .res_o      (res_o),
    .fill_o     (fill_o)
  );

  always #5 clk = ~clk;

  int          c;                      // cycles since reset rose
  int          la_at   [RING];         // lookahead length due at a cycle (-1: none)
  bit          push_at [RING];         // a burst flit written at a cycle
  int          due_at  [RING];         // the model's release: burst length (-1: nothing due)
  int          res_m, fill_m;          // the model
  bit          p_dec, p_s0, p_mode;
  int          p_src, p_l, p_b, p_t;
  int unsigned slots_ph, phase, ph_end, ph_len, st_len;
  bit          rdy;
  bit          kept_up;               // the core is always ready and the FIFO is down to one flit
  longint unsigned n_dec, n_acc, n_cx, n_cx0, n_acc0, n_nosh, n_shr, n_two, n_cx_stall, n_ready_cx, n_near;
  int          max_sum;
  string       tmode_s;

  function automatic bit is_dec(int cc, output bit s0, output int t);
    int p, k;
    p  = cc % LEN;
    s0 = 1'b0;
    t  = 0;
    if (p == 0) begin
      s0 = 1'b1;
      t  = cc + S;
      return 1'b1;
    end
    if (p < S) return 1'b0;
    k = (p - S) / T;
    if ((p - S) % T == 0 && k < N - 1) begin
      t = cc + T;
      return 1'b1;
    end
    return 1'b0;
  endfunction

  function automatic void plan(int cc);
    bit s0, clash;
    int t, l, b, l0;
    p_dec = 1'b0;
    if (!is_dec(cc, s0, t)) return;
    if (tb_pkg::rng_below(SID, 10) == 0) return;              // no partner in that subslot
    p_dec  = 1'b1;
    p_s0   = s0;
    p_t    = t;
    p_src  = int'(tb_pkg::rng_below(SID, 256));
    p_mode = tb_pkg::rng_chance(SID, 0.5);
    b      = int'(tb_pkg::rng_below(SID, BM + 2));            // 0 .. BM + 1
    if (b > BM) b = BM;                                        // full bursts more often
    if (tb_pkg::rng_chance(SID, 0.25)) b = 0;                  // a no-show
    l0     = 1 + int'(tb_pkg::rng_below(SID, HM));
    p_l = l0;
    p_b = b;
    if (b > 0) begin
      p_b = 0;
      for (int k = 0; k < HM && p_b == 0; k++) begin
        l = 1 + (l0 - 1 + k) % HM;
        clash = 1'b0;
        for (int j = 0; j < b; j++) if (push_at[(t + 2 * l + 3 + j) % RING]) clash = 1'b1;
        if (!clash) begin
          p_l = l;
          p_b = b;
        end
      end
    end
  endfunction

  initial begin
    for (int i = 0; i < RING; i++) begin
      la_at[i]   = -1;
      push_at[i] = 1'b0;
      due_at[i]  = -1;
    end
    res_m = 0; fill_m = 0; c = 0; phase = 0;
    n_dec = 0; n_acc = 0; n_cx = 0; n_cx0 = 0; n_acc0 = 0; n_nosh = 0; n_shr = 0; n_two = 0;
    n_cx_stall = 0; n_ready_cx = 0; n_near = 0; max_sum = 0;
    done = 1'b0;
    slots_ph = $test$plusargs("QUICK") ? 12 : 40;
    rdy = 1'b1;
    kept_up = 1'b1;
    wait (go);
    repeat (3) @(posedge clk);
    @(negedge clk) rst_n = 1'b1;           // cycle 0: the cycle in which reset rises
    ph_len = slots_ph * LEN;
    if (ph_len < 50 * slots_ph) ph_len = 50 * slots_ph;           // small timetables: phases of 600 / 2,000 cycles at least
    st_len = 8 * LEN;
    if (st_len < 300) st_len = 300;
    ph_end = ph_len;
    forever begin
      logic [RB-1:0] slot_c;
      bit            acc, waiting;
      slot_c = RB'(c % RING);
      tb_pkg::n_checks++;
      if (int'(res_o) != res_m || int'(fill_o) != fill_m)
        tb_pkg::fail($sformatf("U10 N=%0d B_MAX=%0d SPACE=%0d cycle %0d: DUT reserved %0d filled %0d, model %0d and %0d",
                               N, BM, SPACE, c, res_o, fill_o, res_m, fill_m));
      `TB_CHECK(fill_m + res_m <= SPACE && fill_m >= 0 && res_m >= 0,
                ("U10 N=%0d cycle %0d: fill %0d + reserved %0d, space %0d", N, c, fill_m, res_m, SPACE))
      if (fill_m + res_m > max_sum) max_sum = fill_m + res_m;
      plan(c);
      case (phase)
        0, 4:    rdy = 1'b1;
        1:       rdy = !tb_pkg::rng_chance(SID + 1, 0.25);
        2:       rdy = !tb_pkg::rng_chance(SID + 1, 0.75);
        default: rdy = 1'b0;
      endcase
      dec      = p_dec;
      dec_s0   = p_s0;
      dec_src  = node_id_t'(p_src);
      dec_mode = p_mode;
      dec_hops = hop_t'(p_l);
      la       = '0;
      la.vld   = (la_at[slot_c] > 0);
      la.len   = BURST_W'((la_at[slot_c] > 0) ? la_at[slot_c] : 0);
      push     = push_at[slot_c];
      pop      = rdy && (fill_m > 0);
      #1;
      if (dec) begin
        acc     = fill_m + res_m + BM <= SPACE;
        waiting = 1'b0;
        for (int i = 1; i < S + T + 2 * HM + 2; i++) if (due_at[(c + i) % RING] >= 0) waiting = 1'b1;
        n_dec++;
        `TB_CHECK(cx.vld == !acc, ("U10 N=%0d cycle %0d: fill %0d reserved %0d: the DUT cancels %0b, the model accepts %0b", N, c,
                                   fill_m, res_m, cx.vld, acc))
        if (cx.vld) begin
          `TB_CHECK(int'(cx.tgt) == p_src && cx.mode == !p_mode,
                    ("U10 N=%0d cycle %0d: token for R%0d mode %0d, expected R%0d mode %0d", N, c, cx.tgt, cx.mode, p_src, !p_mode))
        end
        if (acc) begin
          n_acc++;
          if (p_s0) n_acc0++;
          if (waiting) n_two++;
          res_m += BM;
          due_at[(p_t + 2 * p_l) % RING] = p_b;
          if (p_b > 0) begin
            la_at[(p_t + 2 * p_l) % RING] = p_b;
            for (int j = 0; j < p_b; j++) push_at[(p_t + 2 * p_l + 3 + j) % RING] = 1'b1;
          end
        end else begin
          n_cx++;
          if (p_s0) n_cx0++;
          if (phase >= 1 && phase <= 3) n_cx_stall++;
          if (kept_up) n_ready_cx++;
        end
        if (fill_m + res_m + BM > SPACE - BM) n_near++;
      end else begin
        `TB_CHECK(!cx.vld, ("U10 N=%0d cycle %0d: a cancel token with no decision", N, c))
      end
      if (due_at[slot_c] >= 0) begin
        if (due_at[slot_c] == 0) begin
          res_m -= BM;
          n_nosh++;
        end else begin
          res_m -= BM - due_at[slot_c];
          n_shr++;
        end
        due_at[slot_c] = -1;
      end
      if (push) begin
        fill_m++;
        res_m--;
      end
      if (pop) fill_m--;
      if (phase == 0)                 kept_up = 1'b1;
      else if (phase != 4)            kept_up = 1'b0;
      else if (fill_m <= 1)           kept_up = 1'b1;
      push_at[slot_c] = 1'b0;
      la_at[slot_c]   = -1;
      if (c + 1 >= int'(ph_end)) begin
        phase++;
        if (phase == 3) ph_end = ph_end + st_len;             // the full stall: eight slots, 300 cycles at least
        else            ph_end = ph_end + ph_len;
        if (phase > 4) break;
      end
      @(negedge clk);
      c = c + 1;
    end
    dec   = 1'b0;
    la    = '0;
    push  = 1'b0;
    pop   = 1'b0;
    rst_n = 1'b0;
    `TB_CHECK(n_acc > 0 && n_cx > 0 && n_nosh > 0 && n_shr > 0 && (n_two > 0 || SMALL != 0) && n_acc0 > 0 && n_cx0 > 0 &&
              n_cx_stall > 0 && max_sum >= SPACE - BM + 1,
              ("U10 N=%0d B_MAX=%0d SPACE=%0d: a rule never occurred: accepted %0d, cancelled %0d, no-shows %0d, shrunk %0d, two waiting %0d, subslot 0 accepted %0d cancelled %0d, cancelled while stalled %0d, largest fill + reserved %0d",
               N, BM, SPACE, n_acc, n_cx, n_nosh, n_shr, n_two, n_acc0, n_cx0, n_cx_stall, max_sum))
    if (SMALL == 0) begin
      `TB_CHECK(n_ready_cx == 0, ("U10 N=%0d B_MAX=%0d: %0d turns cancelled while the core was always ready (D48 sizing)", N, BM, n_ready_cx))
    end
    if (TMODE == TM_TIGHT) tmode_s = "TIGHT";
    else                   tmode_s = "SAFE";
    tb_pkg::info($sformatf("U10 N=%0d B_MAX=%0d %s SPACE=%0d: %0d cycles, %0d decisions: %0d accepted (%0d of subslot 0, %0d while another waited), %0d cancelled (%0d while the core stalled, %0d while it kept up); %0d no-shows, %0d shrunk at the lookahead; largest fill + reserved %0d",
                           N, BM, tmode_s, SPACE, c, n_dec, n_acc, n_acc0, n_two, n_cx, n_cx_stall, n_ready_cx, n_nosh, n_shr, max_sum));
    tb_pkg::cover_bin($sformatf("U10 N=%0d B_MAX=%0d SPACE=%0d cancels", N, BM, SPACE), n_cx);
    done = 1'b1;
  end
endmodule

module tb_resv_ctrl;
  import sched_pkg::*;
  logic go = 1'b0;
  logic [5:0] dn;
  resv_tester #(.N(4),  .BM(10), .TMODE(TM_TIGHT), .SMALL(0), .SID(701)) u_t1 (.go(go), .done(dn[0]));
  resv_tester #(.N(8),  .BM(15), .TMODE(TM_TIGHT), .SMALL(0), .SID(703)) u_t2 (.go(go), .done(dn[1]));
  resv_tester #(.N(2),  .BM(5),  .TMODE(TM_TIGHT), .SMALL(0), .SID(705)) u_t3 (.go(go), .done(dn[2]));
  resv_tester #(.N(4),  .BM(10), .TMODE(TM_SAFE),  .SMALL(0), .SID(707)) u_t4 (.go(go), .done(dn[3]));
  resv_tester #(.N(16), .BM(10), .TMODE(TM_TIGHT), .SMALL(0), .SID(709)) u_t5 (.go(go), .done(dn[4]));
  resv_tester #(.N(4),  .BM(10), .TMODE(TM_TIGHT), .SMALL(1), .SID(711)) u_t6 (.go(go), .done(dn[5]));

  initial begin
    tb_pkg::start("U10", "resv_ctrl: reserve, re-check, cancel, shrink, release (six timetable shapes)");
    for (int i = 701; i <= 712; i++) tb_pkg::rng_init(i);
    go = 1'b1;
    wait (&dn);
    tb_pkg::finish();
  end

  initial tb_pkg::watchdog(64'd200_000_000);

  `TB_DUMP(tb_resv_ctrl)
endmodule
`endif // RUN_TB_RESV_CTRL

// =============================================================================
// ==== tb/unit/tb_phase_sequencer.sv   (tests: U11)
// =============================================================================
`ifdef RUN_TB_PHASE_SEQUENCER
// @tests    U11
`timescale 1ns/1ps
// `include "tb_macros.svh": inlined earlier in this bundle

module ps_tester
  import sched_pkg::*;
#(
  parameter int N    = 8,
  parameter int RG   = 4,
  parameter int BM   = 10,
  parameter int MODE = TM_TIGHT,
  parameter int K0   = 4,
  parameter int EP   = 4096,
  parameter int AD   = 256,
  parameter int PFIX = -1,       // >= 0: the plan is held at this value for the first 4 epochs
  parameter int TOT  = 400000,   // cycles to run
  parameter int SID  = 100,      // random stream of this tester
  parameter bit XTAG = 1'b0      // name ends " k0 epoch <EP>" (no empty string parameter: xsim
) (
  input  logic go,
  output logic done
);
  localparam int TG = t_sub(N, BM, MODE);
  localparam int TL = t_sub(RG, BM, MODE);
  localparam int KM = k_max(N);
  localparam bit TWO = (RG < N);

  logic    clk   = 1'b0;
  logic    rst_n = 1'b0;
  kl_t     plan;
  logic    loc, sub_go, nxt_go, tick;
  slot_t   slot_l, slot_g;
  sub_t    sub_l, sub_g, nsub_l, nsub_g;
  kl_t     kl;
  seq_st_t st;

  phase_sequencer #(
    .MESH_N   (N),
    .REGION_N (RG),
    .T_SUB_G  (TG),
    .T_SUB_L  (TL),
    .K_INIT   (K0),
    .EPOCH    (EP),
    .A_DLY    (AD)
  ) u_dut (
    .clk_i       (clk),
    .rst_ni      (rst_n),
    .plan_i      (plan),
    .loc_o       (loc),
    .slot_l_o    (slot_l),
    .sub_l_o     (sub_l),
    .nxt_sub_l_o (nsub_l),
    .slot_g_o    (slot_g),
    .sub_g_o     (sub_g),
    .nxt_sub_g_o (nsub_g),
    .sub_go_o    (sub_go),
    .nxt_go_o    (nxt_go),
    .kl_o        (kl),
    .tick_o      (tick),
    .st_o        (st)
  );

  always #5 clk = ~clk;

  sched_ref_pkg::frame_ref fr;
  string                   name;
  longint unsigned c_apply = 0, c_k0 = 0, c_kmax = 0, c_lg = 0, c_gl = 0, c_now = 0, c_repl = 0;
  longint unsigned c_gwrap = 0, c_tick = 0, c_frames = 0, c_k63 = 0;
  int              k_prev;
  bit              loc_prev;

  task automatic check_cycle(longint e);
    sched_ref_pkg::fpos_t p;
    sched_ref_pkg::pos_t  rp;
    int  s_loc, s_kl, s_lc, s_lset, s_lsub, s_lcyc, s_lslot, s_gset, s_gsub, s_gcyc, s_gslot;
    int  o_loc, o_kl, o_sl, o_bl, o_nl, o_sg, o_bg, o_ng, o_go, o_ngo, o_tick;
    int  x_loc, x_lset, x_gset, x_go, x_ngo, x_nl, x_ng, x_tick, nrun;
    longint epx;
    p       = fr.at(e);
    epx     = longint'(EP);
    x_loc   = p.loc ? 1 : 0;
    x_lset  = p.lp.setup ? 1 : 0;
    x_gset  = p.gp.setup ? 1 : 0;
    s_loc   = int'(st.loc);
    s_kl    = int'(st.kl);
    s_lc    = int'(st.lc);
    s_lset  = int'(st.l_setup);
    s_lsub  = int'(st.l_sub);
    s_lcyc  = int'(st.l_cyc);
    s_lslot = int'(st.l_slot);
    s_gset  = int'(st.g_setup);
    s_gsub  = int'(st.g_sub);
    s_gcyc  = int'(st.g_cyc);
    s_gslot = int'(st.g_slot);
    o_loc   = int'(loc);
    o_kl    = int'(kl);
    o_sl    = int'(slot_l);
    o_bl    = int'(sub_l);
    o_nl    = int'(nsub_l);
    o_sg    = int'(slot_g);
    o_bg    = int'(sub_g);
    o_ng    = int'(nsub_g);
    o_go    = int'(sub_go);
    o_ngo   = int'(nxt_go);
    o_tick  = int'(tick);
    if (p.loc) begin
      rp   = p.lp;
      nrun = RG;
    end else begin
      rp   = p.gp;
      nrun = N;
    end
    x_go   = (!rp.setup && rp.cyc == 0) ? 1 : 0;
    x_ngo  = (rp.cyc == 0 && (rp.setup || rp.sub < nrun - 1)) ? 1 : 0;
    x_nl   = p.lp.setup ? 0 : ((p.lp.sub + 1) & 15);
    x_ng   = p.gp.setup ? 0 : ((p.gp.sub + 1) & 15);
    x_tick = (e % epx == 0) ? 1 : 0;
    `TB_CHECK(s_loc == x_loc && s_kl == p.k && s_lc == p.lc,
      ("%s cycle %0d: phase %0d k_L %0d local slots done %0d; expected %0d %0d %0d", name, e, s_loc, s_kl, s_lc,
       p.loc, p.k, p.lc))
    if (TWO) begin
      `TB_CHECK(s_lset == x_lset && s_lsub == p.lp.sub && s_lcyc == p.lp.cyc && s_lslot == p.lp.slot,
        ("%s cycle %0d: local counter setup %0d subslot %0d cycle %0d slot %0d; expected %0d %0d %0d %0d", name, e,
         s_lset, s_lsub, s_lcyc, s_lslot, p.lp.setup, p.lp.sub, p.lp.cyc, p.lp.slot))
    end else begin
      `TB_CHECK(s_lset == 0 && s_lsub == 0 && s_lcyc == 0 && s_lslot == 0 && o_sl == 0 && o_bl == 0 && o_nl == 0,
        ("%s cycle %0d: one pointer, but the local counter reads setup %0d subslot %0d cycle %0d slot %0d", name, e,
         s_lset, s_lsub, s_lcyc, s_lslot))
    end
    `TB_CHECK(s_gset == x_gset && s_gsub == p.gp.sub && s_gcyc == p.gp.cyc && s_gslot == p.gp.slot,
      ("%s cycle %0d: global counter setup %0d subslot %0d cycle %0d slot %0d; expected %0d %0d %0d %0d", name, e,
       s_gset, s_gsub, s_gcyc, s_gslot, p.gp.setup, p.gp.sub, p.gp.cyc, p.gp.slot))
    `TB_CHECK(o_loc == x_loc && o_kl == p.k && o_go == x_go && o_ngo == x_ngo && o_tick == x_tick,
      ("%s cycle %0d: loc %0d k_L %0d sub_go %0d nxt_go %0d tick %0d; expected %0d %0d %0d %0d %0d", name, e,
       o_loc, o_kl, o_go, o_ngo, o_tick, p.loc, p.k, x_go, x_ngo, x_tick))
    if (TWO) begin
      `TB_CHECK(o_sl == p.lp.slot && o_bl == p.lp.sub && o_nl == x_nl,
        ("%s cycle %0d: local slot %0d subslot %0d next %0d; expected %0d %0d %0d", name, e, o_sl, o_bl, o_nl,
         p.lp.slot, p.lp.sub, x_nl))
    end
    `TB_CHECK(o_sg == p.gp.slot && o_bg == p.gp.sub && o_ng == x_ng,
      ("%s cycle %0d: global slot %0d subslot %0d next %0d; expected %0d %0d %0d", name, e, o_sg, o_bg, o_ng,
       p.gp.slot, p.gp.sub, x_ng))
    if (p.fstart) begin
      c_frames++;
      if (e > 0 && p.k != k_prev) c_apply++;
      if (p.k == 0)  c_k0++;
      if (p.k == KM) c_kmax++;
      if (p.k == 63) c_k63++;
      k_prev = p.k;
    end
    if (e > 0 && loc_prev && !p.loc) c_lg++;
    if (e > 0 && !loc_prev && p.loc) c_gl++;
    if (!p.loc && e > 0 && p.gp.setup && p.gp.cyc == 0 && p.gp.slot == 0) c_gwrap++;
    if (x_tick == 1) c_tick++;
    loc_prev = p.loc;
  endtask

  initial begin
    longint e, total, tq, epl, adl;
    int     r, nv, kp;
    kl_t    kk;
    bit     quick;
    string  mname;
    done = 1'b0;
    wait (go === 1'b1);
    tb_pkg::rng_init(SID);
    quick = $test$plusargs("QUICK");
    tq    = longint'(TOT);
    epl   = longint'(EP);
    adl   = longint'(AD);
    total = quick ? tq / 8 : tq;
    if (MODE == TM_TIGHT) mname = "TIGHT";
    else                  mname = "SAFE";
    if (TWO && XTAG) name = $sformatf("%0dx%0d/%0d %s B%0d k0 epoch %0d", N, N, RG, mname, BM, EP);
    else if (TWO)    name = $sformatf("%0dx%0d/%0d %s B%0d", N, N, RG, mname, BM);
    else             name = $sformatf("%0dx%0d one pointer", N, N);
    fr       = new(N, RG, TL, TG, K0);
    k_prev   = TWO ? K0 : 0;
    loc_prev = 1'b0;
    if (PFIX >= 0) plan = kl_t'(PFIX);
    else           plan = kl_t'(K0);
    repeat (2) @(posedge clk);
    #1 rst_n = 1'b1;
    for (e = 0; e < total; e++) begin
      @(negedge clk);
      check_cycle(e);
      r = int'(tb_pkg::rng_below(SID, 400));
      if (r == 0 && !(PFIX >= 0 && e < 4 * epl)) begin
        nv = int'(tb_pkg::rng_below(SID, 20));
        if (nv < 5)      kk = '0;
        else if (nv < 8) kk = kl_t'(KM);
        else if (nv < 9) kk = '1;                 // 63, the largest k_L the register holds
        else begin                                // 1 .. KM - 1 (no cast inside an expression: rule 9)
          nv = int'(tb_pkg::rng_below(SID, KM - 1));
          nv = nv + 1;
          kk = kl_t'(nv);
        end
        plan = kk;
      end
      if (e % epl == adl - 1) begin
        kp = int'(plan);                          // never a cast as an argument (R-1110-02)
        r  = fr.sample(e, kp);
        if (r == 2) c_repl++;
        if (r == 1 && fr.last_start() == e + 1) c_now++;
      end
    end
    tb_pkg::info($sformatf("U11 %s: %0d cycles, %0d frames, %0d plan changes applied, local/global slots %0d/%0d cycles",
                           name, total, c_frames, c_apply, slot_len(RG, TL), slot_len(N, TG)));
    tb_pkg::cover_bin($sformatf("U11 %s frame starts", name), c_frames);
    tb_pkg::cover_bin($sformatf("U11 %s epoch ticks", name), c_tick);
    if (TWO) begin
      tb_pkg::cover_bin($sformatf("U11 %s new k_L applied at a frame start", name), c_apply);
      if (quick) begin
        tb_pkg::cover_goal($sformatf("U11 %s frames with k_L = 0 (global only)", name), c_k0);
        tb_pkg::cover_goal($sformatf("U11 %s frames with k_L = K_MAX", name), c_kmax);
      end else begin
        tb_pkg::cover_bin($sformatf("U11 %s frames with k_L = 0 (global only)", name), c_k0);
        tb_pkg::cover_bin($sformatf("U11 %s frames with k_L = K_MAX", name), c_kmax);
      end
      tb_pkg::cover_bin($sformatf("U11 %s local -> global at a slot end", name), c_lg);
      tb_pkg::cover_bin($sformatf("U11 %s global -> local at a frame start", name), c_gl);
      if (PFIX >= 0)
        tb_pkg::cover_bin($sformatf("U11 %s sample in a frame's last cycle, applied at once", name), c_now);
      else
        tb_pkg::cover_goal($sformatf("U11 %s sample in a frame's last cycle, applied at once", name), c_now);
      tb_pkg::cover_goal($sformatf("U11 %s sample replaced before taking effect", name), c_repl);
      tb_pkg::cover_goal($sformatf("U11 %s frames with k_L = 63 (register limit)", name), c_k63);
    end
    tb_pkg::cover_goal($sformatf("U11 %s global slot number wraps to 0", name), c_gwrap);
    done = 1'b1;
  end

endmodule


module tb_phase_sequencer;
  import sched_pkg::*;

  logic       go = 1'b0;
  logic [8:0] done;

  ps_tester #(.N(8),  .RG(4), .BM(10), .MODE(TM_TIGHT), .K0(4),  .EP(4096), .AD(256), .TOT(400000), .SID(100)) t_8a (.go(go), .done(done[0]));
  ps_tester #(.N(8),  .RG(4), .BM(10), .MODE(TM_SAFE),  .K0(3),  .EP(1024), .AD(7),   .TOT(400000), .SID(101)) t_8b (.go(go), .done(done[1]));
  ps_tester #(.N(8),  .RG(2), .BM(5),  .MODE(TM_TIGHT), .K0(k_fixed(8, 2, 5, TM_TIGHT)), .EP(2048), .AD(1), .TOT(400000), .SID(102)) t_8c (.go(go), .done(done[2]));
  ps_tester #(.N(16), .RG(4), .BM(10), .MODE(TM_TIGHT), .K0(14), .EP(2048), .AD(256), .TOT(600000), .SID(103)) t_16a (.go(go), .done(done[3]));
  ps_tester #(.N(16), .RG(8), .BM(15), .MODE(TM_SAFE),  .K0(k_fixed(16, 8, 15, TM_SAFE)), .EP(8192), .AD(100), .TOT(600000), .SID(104)) t_16b (.go(go), .done(done[4]));
  ps_tester #(.N(4),  .RG(2), .BM(10), .MODE(TM_TIGHT), .K0(3),  .EP(512),  .AD(100), .TOT(200000), .SID(105)) t_4a (.go(go), .done(done[5]));
  ps_tester #(.N(4),  .RG(4), .BM(10), .MODE(TM_TIGHT), .K0(1),  .EP(512),  .AD(100), .TOT(200000), .SID(106)) t_4o (.go(go), .done(done[6]));
  ps_tester #(.N(8),  .RG(8), .BM(10), .MODE(TM_TIGHT), .K0(1),  .EP(1024), .AD(256), .TOT(400000), .SID(107)) t_8o (.go(go), .done(done[7]));
  ps_tester #(.N(8),  .RG(4), .BM(10), .MODE(TM_TIGHT), .K0(0),  .EP(1148), .AD(287), .PFIX(5), .TOT(400000), .SID(108), .XTAG(1'b1)) t_8d (.go(go), .done(done[8]));

  `TB_DUMP(tb_phase_sequencer)

  initial tb_pkg::watchdog(100ms);

  task automatic pkg_numbers();
    int got [13];
    int exp [13];
    got[0]  = k_fixed(8, 4, 10, TM_TIGHT);
    got[1]  = k_fixed(16, 4, 10, TM_TIGHT);
    got[2]  = k_fixed(8, 4, 10, TM_SAFE);
    got[3]  = k_fixed(16, 4, 10, TM_SAFE);
    got[4]  = frame_len(8, 4, 10, TM_TIGHT, 4);
    got[5]  = frame_len(8, 4, 10, TM_TIGHT, 3);
    got[6]  = frame_len(8, 4, 10, TM_TIGHT, 15);
    got[7]  = frame_len(16, 4, 10, TM_TIGHT, 14);
    got[8]  = epoch_len(8, 4, 10, TM_TIGHT);
    got[9]  = epoch_len(16, 4, 10, TM_TIGHT);
    got[10] = k_max(8);
    got[11] = k_max(16);
    got[12] = epoch_len(8, 4, 5, TM_TIGHT);   // a round at k_L = 4: 36 x 483 = 17,388
    exp = '{4, 14, 3, 11, 603, 524, 1472, 2193, 32768, 262144, 15, 47, 32768};
    for (int i = 0; i < 13; i++)
      `TB_CHECK(got[i] == exp[i], ("U11 sched_pkg number %0d (K_FIXED 8x8, 16x16, SAFE 8x8, 16x16; frames k 4, 3, 15, 16x16 k 14; epochs; K_MAX; epoch 8x8 B_MAX 5): %0d, the tracker says %0d",
                                   i, got[i], exp[i]))
  endtask

  initial begin
    tb_pkg::start("U11", "phase_sequencer: frames, resumed counters, epoch and plan switch equal the frame reference every cycle");
    pkg_numbers();
    go = 1'b1;
    wait (&done === 1'b1);
    tb_pkg::info("U11 sequencers: 8x8/4 TIGHT and SAFE, 8x8/2 B5, 16x16/4, 16x16/8 SAFE B15, 4x4/2, one pointer on 4x4 and 8x8, a sample at a frame's end");
    tb_pkg::finish();
  end

endmodule
`endif // RUN_TB_PHASE_SEQUENCER

